function lineBreakdown(r){const item=r.item||r.position||"Item";if(r.category==="PS")return `${r.position||item} · ${r.staff_count||0} staff × ${r.hours||0} hours × ${money(r.hourly_rate)}/hour`;if(r.category==="MATERIALS")return `${item} · ${r.quantity||0} × ${money(r.unit_price)}`;if(r.category==="VENUE/FOOD")return `${item} · ${r.quantity||0} packs × ${money(r.unit_price)}/pack`;if(r.category==="PATIENT EXPENSE")return `${item} · ${r.patients||0} patients × ${r.quantity||0} per patient × ${money(r.unit_price)}`;if(r.category==="HONORARIA")return `${item} · ${money(r.rate_per_hour)}/hour × ${r.hours||0} hours`;return item;}
function Field({label,value,onChange,type="text",wide=false,placeholder="",readOnly=false}){return <label className={wide?"field wide":"field"}><span>{label}</span>{type==="textarea"?<textarea value={value??""} onChange={e=>onChange(e.target.value)} placeholder={placeholder} readOnly={readOnly}/>:<input type={type} value={value??""} onChange={e=>onChange(type==="number"?(e.target.value===""?"":Number(e.target.value)):e.target.value)} placeholder={placeholder} readOnly={readOnly}/>}</label>}
